// NewRadioGroup creates a new radio group widget with the set options and change handler
//
// Since: 1.4
func NewRadioGroup(options []string, changed func(string)) *RadioGroup {
	r := &RadioGroup{
		DisableableWidget: DisableableWidget{},
		Options:           options,
		OnChanged:         changed,
	}
	r.ExtendBaseWidget(r)
	r.update()
	return r
}

// NewAllStrings creates a new RadioGroup widget with all the provided options visible.
// This is a convenience constructor that is equivalent to NewRadioGroup but emphasizes
// that all strings will be displayed as selectable options.
//
// Since: 2.2
func NewAllStrings(options []string, changed func(string)) *RadioGroup {
	return NewRadioGroup(options, changed)
}

// Append adds a new option to the end of a RadioGroup widget.

